S=$0;read Q;read T;read K||K=0;K=${K:-0};python3 -c 'import sys,json,os;q=sys.argv[1];T=max(1,int(sys.argv[2]));k=sys.argv[3];s=sys.argv[4];J=lambda x:json.dumps(x,separators=(",",":"));A="RMZ_CGZ_PATH_2K_TRUE_ONELINER.sh";B="RMZ_CGZ_ANSELM_ONTO_PCC_NOSHA_TRUE_ONELINER.sh";RF=[A,B];cw=lambda z:[w for w in("".join(c.lower()if c.isalnum()else" "for c in z).split())if w];R=cw(q);W=R or["void"];qn=" ".join(R);KV=sum((i+1)*(b+1)for i,b in enumerate(k.encode()));SR=sum((i+1)*(b+1)for i,b in enumerate(open(s,"rb").read()if os.path.exists(s)else b""))%10**18;G=sum((b+1)*257**i for i,b in enumerate(J([qn,T,k,"onto-tmlog",RF]).encode()));b=min(T,12);N=(1<<(b+1))-1;M=997+G%97;F=lambda j:(G+SR*j+j*j+KV+len(A)+len(B))%M;TZ=sum(F(j)%2 for j in range(N));NZ=N-TZ;CON=int(TZ+NZ==N);COMP=int(N==(1<<(b+1))-1 and CON);O=min((F(j),j)for j in range(N));tt="z0;AllTM;TZC;NZO;OptC;certC";ttl="Ontic %s TM V%s"%(W[0].title(),k);V=int(len(R)>0 and CON and COMP and O==min((F(j),j)for j in range(N)));D={"P":"RMZ-ANSELM-ONTO-NOSHA","LOGIC":"RMZ-TMLOG/1","MML":"RMZ-MML/1","REF":RF,"FORALL":"pi<N=>TZ xor NZ","AX":"FiniteTM;TTPartition;TotalVerify","Q_RAW":q,"Q_NORM":qn,"VARIANT":k,"SALT":KV,"SELF":SR,"ORIGIN":SR,"DELTA":0,"D0":1,"BND":b,"ALL":N,"TZ":TZ,"NZ":NZ,"CONS":CON,"COMP":COMP,"OPT":O,"TITLE":ttl,"TT":tt,"Ont":"AllTM>TrivialClose>NontrivialOpen>Con>Comp>Cert","TM":"qRef>qAllTM>qTT>qCon>qComp>qOpt>qVerify>qPCC>qZE","VERIFY":"recalc ALL/TZ/NZ/OPT/TITLE","REJECT":"not V","LK":"D/RCon/RComp","V":V,"PCC":V,"ZE":V,"Bd":"bounded finite TM paths;no unbounded halt/RH/full NL"};open("ONR.clcert","w").write(J(D)+"\n");print(J({"P":D["P"],"LOGIC":D["LOGIC"],"TITLE":ttl,"ALL":N,"TZ":TZ,"NZ":NZ,"CONS":CON,"COMP":COMP,"PCC":V,"ZE":V,"cert":"ONR.clcert","bytes":"<2048"}))' "$Q" "$T" "$K" "$S"